                    Json(json!({"detail":"speech worker is unavailable or busy"})),
                )
                    .into_response()
            }
        }
    };

    let route = state.0.live_leg.route();
    if let Some(entry) = state
        .0
        .transcript_log
        .lock()
        .await
        .add(AGENT, &req.text, route)
    {
        emit_json(&state, json!({"type":"spoken", "entry":entry}));
    }

